<template>
  <AccountLayout bare>
    <main class="company-page"><div class="company-shell">
      <header><h1>Company Profile</h1><small>Last Updated: {{ lastUpdated }}</small></header>
      <div v-if="message" class="company-alert success">{{ message }}</div><div v-if="error" class="company-alert error">{{ error }}</div>
      <form @submit.prevent="save">
        <section><h2>1. Company Details</h2><div class="company-details-columns">
          <div class="company-detail-stack"><Field label="Legal Name"><input v-model.trim="form.company_name" required /></Field><Field label="Trading Name"><input v-model.trim="form.business_location" /></Field><Field label="Director Name"><input v-model.trim="form.director_name" /></Field></div>
          <div class="company-detail-stack"><Field label="Company Logo"><div class="logo-upload" role="button" tabindex="0" @click="logoInput?.click()" @keydown.enter.prevent="logoInput?.click()"><input ref="logoInput" type="file" accept="image/png,image/jpeg,image/svg+xml" @change="uploadLogo" /><span><svg viewBox="0 0 48 40"><path d="M24 31V9m0 0-8 8m8-8 8 8M13 31H9a7 7 0 0 1-.6-14A11 11 0 0 1 29 12a9 9 0 0 1 10 9 10 10 0 0 1-1 4" /></svg><b>Click to upload</b><small>PNG, JPG or SVG</small></span></div></Field><Field label="Business Type"><select v-model="form.business_type"><option value="">Select business type</option><option>Operate as a Company</option><option>Sole Proprietorship</option><option>Partnership</option><option>Corporation</option></select></Field></div>
          <div class="company-detail-stack"><Field label="Company Logo Display"><div class="logo-display"><img v-if="form.company_logo_url" :src="form.company_logo_url" alt="Company logo" /><span v-else>No logo uploaded</span></div></Field><Field label="Website"><input v-model.trim="form.contact_website" /></Field></div>
        </div></section>
        <div class="company-split"><section><h2>2. Contact Info</h2><div class="company-grid two"><Field label="Email Address"><input v-model.trim="form.contact_business_email" type="email" /></Field><Field label="Phone Number"><input v-model.trim="form.contact_primary_phone" /></Field></div></section><section><h2>3. Company Registration</h2><div class="company-grid registration"><Field label="Registration Number"><input v-model.trim="form.business_registration_number" /></Field><Field label="Registration Date"><input v-model="form.incorporation_date" type="date" /></Field><Field label="Registered Country"><input v-model.trim="form.registration_country" /></Field><Field label="State / Province"><input v-model.trim="form.registration_province" /></Field><Field label="City"><input v-model.trim="form.company_city" /></Field></div></section></div>
        <div class="company-split address-tax"><section><h2>4. Address &amp; Location</h2><div class="company-grid address"><Field label="Street Address"><input v-model.trim="form.company_address" /></Field><Field label="Country"><select v-model.number="form.company_country_id"><option :value="null">Select country</option><option v-for="country in countries" :key="country.id" :value="country.id">{{ country.country_name }}</option></select></Field><Field label="State / Province"><input v-model.trim="form.company_state" /></Field><Field label="City"><input v-model.trim="form.company_city" /></Field><Field label="ZIP / Postal Code"><input v-model.trim="form.company_zip" /></Field><Field label="Map Link"><input v-model.trim="form.business_location" /></Field></div></section><section><h2>5. Tax Info</h2><Field label="Tax Number"><input v-model.trim="form.tax_number" /></Field></section></div>
        <section class="company-status"><h2>6. Company Status</h2><div><Field label="Status"><span class="radios"><label><input v-model="form.company_status" value="Active" type="radio" /> Active</label><label><input v-model="form.company_status" value="Inactive" type="radio" /> Inactive</label></span></Field><label class="confirmation"><input v-model="form.company_profile_confirmation" type="checkbox" /> I confirm that the company is legally registered in the selected country and that the information provided is correct.</label></div></section>
        <div class="company-actions"><button class="company-button outline" type="button" @click="load">Reset</button><button class="company-button primary" :disabled="saving">{{ saving ? 'Saving...' : 'Save' }}</button></div>
      </form>
    </div></main>
  </AccountLayout>
</template>
<script setup>
import { computed, defineComponent, h, onMounted, ref } from 'vue'
import AccountLayout from '../components/AccountLayout.vue'
import client from '../api/client'
import { setFlash } from '../store/flash'
const Field = defineComponent({ props: { label: String }, setup: (props, { slots }) => () => h('label', { class: 'company-field' }, [h('span', props.label), slots.default?.()]) })
const empty = () => ({ company_name:'', company_logo_url:'', contact_website:'', business_location:'', business_type:'', director_name:'', contact_business_email:'', contact_primary_phone:'', business_registration_number:'', incorporation_date:'', registration_country:'', registration_province:'', company_city:'', company_address:'', company_country_id:null, company_state:'', company_zip:'', tax_number:'', company_status:'Active', company_profile_confirmation:false })
const form = ref(empty()), countries = ref([]), saving = ref(false), error = ref(''), message = ref(''), updatedAt = ref(null), logoInput = ref(null)
const lastUpdated = computed(() => updatedAt.value ? new Date(updatedAt.value).toLocaleString() : 'Not updated yet')
const load = async () => { error.value=''; try { const [{ data }, countryResponse] = await Promise.all([client.get('/account/company-profile'), client.get('/countries')]); form.value={...empty(), ...(data.data || {})}; form.value.company_profile_confirmation=Boolean(data.data?.company_profile_confirmation); updatedAt.value=data.data?.updated_at; countries.value=countryResponse.data?.data || [] } catch (e) { error.value=e?.response?.data?.message || 'Unable to load company profile.' } }
const uploadLogo = async (event) => { const file=event.target.files?.[0]; if (!file) return; error.value=''; const payload=new FormData(); payload.append('logo', file, file.name); try { const { data }=await client.post('/account/company-profile/logo', payload, { headers: { 'Content-Type': 'multipart/form-data' } }); form.value.company_logo_url=data.data.url; message.value='Company logo uploaded successfully.' } catch (e) { error.value=e?.response?.data?.message || 'Unable to upload logo.' } finally { event.target.value='' } }
const save = async () => { message.value=''; error.value=''; saving.value=true; try { const { data }=await client.put('/account/company-profile', form.value); form.value={...empty(), ...(data.data || {})}; form.value.company_profile_confirmation=Boolean(data.data?.company_profile_confirmation); updatedAt.value=data.data?.updated_at; message.value='Company profile updated successfully.'; setFlash('Company profile updated.', 'success', 2000) } catch (e) { error.value=e?.response?.data?.message || 'Unable to save company profile.' } finally { saving.value=false } }
onMounted(load)
</script>
<style scoped>
.company-page{min-height:100%;padding:18px 36px;background:#fafafa;color:#092c67}.company-shell{max-width:1180px}.company-shell header{display:flex;align-items:center;justify-content:space-between;margin-bottom:16px}.company-shell h1{margin:0;font-size:2.45rem;font-weight:800;letter-spacing:-.04em}.company-shell header small{font-size:.9rem;font-weight:700}.company-shell h2{margin:0 0 7px;font-size:1.15rem;font-weight:800}.company-shell section{padding:0 0 10px;margin-bottom:10px;border-bottom:1px solid #d7d7d7}.company-grid{display:grid;gap:8px 28px}.company-details-columns{display:grid;grid-template-columns:1.15fr .78fr 1.08fr;gap:28px}.company-detail-stack{display:grid;align-content:start;gap:10px}.company-field{display:grid;gap:4px;font-size:.78rem;font-weight:800}.company-field input,.company-field select{width:100%;height:32px;padding:4px 8px;border:1px solid #b9b9bd;border-radius:5px;background:#efeff1;font-size:.82rem;outline:none}.company-field input:focus,.company-field select:focus{border-color:#0870ef;background:#fff}.logo-upload,.logo-display{height:130px;border-radius:5px;display:grid;place-items:center;overflow:hidden}.logo-upload{border:1px dashed #b9b9bd;cursor:pointer;background:#efeff1}.logo-upload:focus{outline:2px solid #0870ef;outline-offset:2px}.logo-upload input{display:none}.logo-upload span{display:grid;gap:2px;place-items:center;color:#0a3372}.logo-upload svg{width:40px;height:35px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}.logo-upload small{font-size:.72rem;color:#697184}.logo-display{border:1px solid #b9b9bd;background:#efeff1;color:#697184;font-size:.75rem}.logo-display img{max-width:100%;max-height:100%;object-fit:contain}.company-split{display:grid;grid-template-columns:.86fr 1.14fr;gap:28px}.company-split>section+section{padding-left:28px;border-left:1px solid #d7d7d7}.two{grid-template-columns:1fr 1fr}.registration{grid-template-columns:repeat(3,1fr)}.address-tax{grid-template-columns:1.2fr .8fr}.address{grid-template-columns:repeat(3,1fr)}.company-status>div{display:grid;grid-template-columns:300px 1fr;gap:24px;align-items:end}.radios{display:flex;gap:26px;font-size:.82rem;font-weight:500}.radios label,.confirmation{display:flex;gap:7px;align-items:center}.radios input,.confirmation input{accent-color:#0870ef}.confirmation{font-size:.79rem;font-weight:500}.company-actions{display:flex;gap:20px;padding:14px 0 0}.company-button{width:180px;height:60px;border-radius:9px;font-size:1.12rem;font-weight:800;box-shadow:none}.company-button.outline{border:2px solid #0870ef;color:#0870ef;background:#fff}.company-button.primary{border:2px solid #0870ef;color:#fff;background:#0870ef}.company-button:disabled{opacity:.65}.company-alert{margin:-8px 0 10px;padding:7px 10px;border-radius:6px;font-size:.82rem;font-weight:600}.company-alert.success{color:#126638;background:#e8f8ee}.company-alert.error{color:#9f1e2f;background:#fdecee}@media(max-width:900px){.company-page{padding:18px}.company-details-columns,.company-split,.address-tax,.registration,.address,.company-status>div{grid-template-columns:1fr}.company-split>section+section{padding-left:0;border-left:0}.company-shell header{align-items:flex-start;gap:8px;flex-direction:column}.company-button{width:150px;height:54px}}
</style>
